  task: () => Promise<T>,
  options: RetryOptions,
  sleep: Sleep = defaultSleep,
): Promise<T> {
  let lastError: unknown;
  for (let attempt = 0; attempt < options.attempts; attempt++) {
    try {
      return await task();
    } catch (error) {
      lastError = error;
      if (attempt < options.attempts - 1) {
